import net.minecraft.world.*;

/** Actual placed rig, durable source assembly, real player transmitter input and normal world ticks. */
public final class VehicleArmCouplerLiveChecks {
    private static int stage,frames,checks;private static VehicleScan scan;private static UUID id;private static BlockPos localArm;private static long started;private static boolean done,reloaded;private static net.minecraft.util.math.Vec3d controlAim;
    private static WorldServer world(Minecraft mc){return mc.getIntegratedServer().getWorld(0);}
    private static EntityPlayerMP actor(Minecraft mc){return mc.getIntegratedServer().getPlayerList().getPlayers().get(0);}
    private static EntityGroundVehicle craft(Minecraft mc){return id==null?null:(EntityGroundVehicle)world(mc).getEntityFromUuid(id);}
    private static void need(boolean v,String why){checks++;if(!v)throw new IllegalStateException("Carried arm Coupler live: "+why+" stage="+stage+" frames="+frames);}
    private static void closed(EntityGroundVehicle craft){
        need(craft.articulation.jointCount()==1,"closed bridge retained");VehicleArmCouplers.Snapshot observed=VehicleArmCouplers.observe(craft);need(observed.heads.size()==2,"exactly two owned heads");net.minecraft.util.math.Vec3d first=craft.toWorld(new net.minecraft.util.math.Vec3d(observed.heads.get(0).x,observed.heads.get(0).y,observed.heads.get(0).z),observed.heads.get(0).carrier),second=craft.toWorld(new net.minecraft.util.math.Vec3d(observed.heads.get(1).x,observed.heads.get(1).y,observed.heads.get(1).z),observed.heads.get(1).carrier);need(first.squareDistanceTo(second)<1e-12,"independent current world head points coincide: "+first+" / "+second);need(craft.articulation.validPose(),"current coupled frame collision safe: "+craft.articulation.lastObstruction);
    }
    private static void transmitter(Minecraft mc)throws Exception{
        need(mc.playerController.getCurrentGameType()==GameType.CREATIVE&&mc.player.inventory.currentItem==0&&mc.player.getHeldItemMainhand().getItem()==ModItems.REDSTONE_TRANSMITTER,"client mode/slot/held state before actual input");mc.player.setSneaking(false);mc.player.rotationPitch=-90;mc.player.connection.sendPacket(new net.minecraft.network.play.client.CPacketHeldItemChange(0));mc.player.connection.sendPacket(new net.minecraft.network.play.client.CPacketPlayer.Rotation(mc.player.rotationYaw,-90,false));mc.playerController.processRightClick(mc.player,mc.world,EnumHand.MAIN_HAND);started=mc.getIntegratedServer().callFromMainThread(()->world(mc).getTotalWorldTime()).get();
    }
    public static boolean tick(Minecraft mc,File output)throws Exception{
        if(done)return true;mc.gameSettings.pauseOnLostFocus=false;need(++frames<1800,"timeout");
        if(stage==0){mc.displayGuiScreen(null);mc.getIntegratedServer().addScheduledTask(()->VehicleArmCouplerFixture.setup(world(mc),actor(mc))).get();stage=1;frames=0;return false;}
        if(stage==1){if(frames<30||mc.playerController.getCurrentGameType()!=GameType.CREATIVE||mc.player.inventory.currentItem!=0||mc.player.getHeldItemMainhand().getItem()!=ModItems.REDSTONE_TRANSMITTER)return false;mc.getIntegratedServer().addScheduledTask(()->{scan=new VehicleScan(world(mc),VehicleArmCouplerFixture.BASE.add(VehicleArmCouplerFixture.SEAT));}).get();stage=2;frames=0;return false;}
        if(stage==2){boolean ready=mc.getIntegratedServer().callFromMainThread(()->scan.step(256)).get();if(!ready)return false;mc.getIntegratedServer().addScheduledTask(()->{try{need(scan.result!=null,"actual placed rig scan: "+scan.error);BlockPos origin=scan.origin;localArm=VehicleArmCouplerFixture.BASE.add(VehicleArmCouplerFixture.ARM).subtract(origin);EntityGroundVehicle craft=VehicleTransfer.assemble(world(mc),scan.result,origin,actor(mc));id=craft.getUniqueID();need(craft.articulation.jointCount()==1,"native placed heads initially create one articulated bridge");need(craft.setHover(true),"actual supported Hover admission");need(craft.board(actor(mc)),"real player boards pilot seat");VehicleNetwork.send(actor(mc),craft.structure,craft.getEntityId(),id,new BlockPos(craft),false,false);VehicleNetwork.state(craft);started=world(mc).getTotalWorldTime();}catch(Exception failure){throw new IllegalStateException(failure);}}).get();stage=3;frames=0;return false;}
        if(stage==3){net.minecraft.entity.Entity raw=mc.world.getEntityByID(mc.player.getRidingEntity()==null?-1:mc.player.getRidingEntity().getEntityId());if(frames<20||!(raw instanceof EntityGroundVehicle)||!raw.getUniqueID().equals(id)||((EntityGroundVehicle)raw).structure==null||mc.playerController.getCurrentGameType()!=GameType.CREATIVE||mc.player.getHeldItemMainhand().getItem()!=ModItems.REDSTONE_TRANSMITTER)return false;transmitter(mc);stage=4;frames=0;return false;}
        if(stage==4){boolean settled=mc.getIntegratedServer().callFromMainThread(()->{EntityGroundVehicle craft=craft(mc);need(craft!=null,"placed craft remains installed");GearTileEntity arm=(GearTileEntity)craft.view.getTileEntity(localArm);long elapsed=world(mc).getTotalWorldTime()-started;String status=VehicleArmCouplerFixture.status(craft,localArm);if(arm.target()){need(elapsed<40,"real transmitter input reaches carried configured arm: "+status);return false;}if(arm.payload()==null||arm.payload().materialized()){need(elapsed<200,"bounded attachment preparation: "+status);return false;}closed(craft);need(elapsed<200,"full coupled stroke after bounded preparation: "+status);if(arm.progress()!=0)return false;System.out.println("[vandorlabs][reprolab] carried-arm-coupler extended "+status);return true;}).get();if(!settled)return false;stage=5;frames=0;return false;}
        if(stage==5){if(frames<15)return false;transmitter(mc);stage=6;frames=0;return false;}
        if(stage==6){boolean settled=mc.getIntegratedServer().callFromMainThread(()->{EntityGroundVehicle craft=craft(mc);GearTileEntity arm=(GearTileEntity)craft.view.getTileEntity(localArm);long elapsed=world(mc).getTotalWorldTime()-started;String status=VehicleArmCouplerFixture.status(craft,localArm);if(!arm.target()){need(elapsed<40,"actual reverse transmitter reaches same installed owner: "+status);return false;}closed(craft);need(elapsed<240,"reverse coupled stroke: "+status);
            if(!reloaded&&arm.progress()>.25&&arm.progress()<.8){double progress=arm.progress();net.minecraft.nbt.NBTTagCompound saved=craft.writeToNBT(new net.minecraft.nbt.NBTTagCompound());EntityPlayerMP player=actor(mc);player.dismountRidingEntity();craft.setDead();world(mc).removeEntityDangerously(craft);EntityGroundVehicle replacement=new EntityGroundVehicle(world(mc));replacement.readFromNBT(saved);need(world(mc).spawnEntity(replacement),"moving saved owner publishes replacement");need(replacement.structure!=null,"moving saved layout remains usable rather than inert");GearTileEntity restored=(GearTileEntity)replacement.view.getTileEntity(localArm);need(restored!=null&&Double.doubleToLongBits(restored.progress())==Double.doubleToLongBits(progress),"saved midpoint keeps exact authoritative arm phase");need(replacement.board(player),"real pilot remounts restored owner");VehicleNetwork.send(player,replacement.structure,replacement.getEntityId(),replacement.getUniqueID(),new BlockPos(replacement),false,false);VehicleNetwork.state(replacement);closed(replacement);reloaded=true;return false;}
            return reloaded&&arm.progress()==1;}).get();if(!settled)return false;stage=7;frames=0;return false;}
        if(stage==7){mc.getIntegratedServer().addScheduledTask(()->{EntityGroundVehicle craft=craft(mc);VehicleArmCouplers.Head head=null;for(VehicleArmCouplers.Head candidate:VehicleArmCouplers.observe(craft).heads)if(candidate.address.arm!=null)head=candidate;need(head!=null,"captured head available for exact player interaction");controlAim=craft.toWorld(new net.minecraft.util.math.Vec3d(head.x-head.nx*.5,head.y-head.ny*.5,head.z-head.nz*.5),head.carrier);EntityPlayerMP player=actor(mc);player.dismountRidingEntity();player.inventory.currentItem=0;player.inventory.setInventorySlotContents(0,new net.minecraft.item.ItemStack(ModItems.CONFIGURIZER));player.inventoryContainer.detectAndSendChanges();player.setSneaking(true);player.setPositionAndUpdate(controlAim.x+2.5,controlAim.y+.1-player.getEyeHeight(),controlAim.z);}).get();stage=8;frames=0;return false;}
        if(stage==8){if(frames<20||mc.player.getRidingEntity()!=null||mc.player.getHeldItemMainhand().getItem()!=ModItems.CONFIGURIZER)return false;net.minecraft.util.math.Vec3d d=controlAim.subtract(mc.player.getPositionEyes(1));float yaw=(float)(Math.toDegrees(Math.atan2(d.z,d.x))-90),pitch=(float)-Math.toDegrees(Math.atan2(d.y,Math.hypot(d.x,d.z)));mc.player.rotationYaw=yaw;mc.player.rotationPitch=pitch;mc.player.setSneaking(true);mc.player.connection.sendPacket(new net.minecraft.network.play.client.CPacketEntityAction(mc.player,net.minecraft.network.play.client.CPacketEntityAction.Action.START_SNEAKING));mc.player.connection.sendPacket(new net.minecraft.network.play.client.CPacketPlayer.Rotation(yaw,pitch,false));mc.getIntegratedServer().addScheduledTask(()->{actor(mc).rotationYaw=yaw;actor(mc).rotationPitch=pitch;}).get();stage=9;frames=0;return false;}
        if(stage==9){if(frames<8)return false;VehicleInteraction.Target target=VehicleInteraction.pointed(mc.player);need(target!=null&&target.craft.getUniqueID().equals(id),"actual camera ray reaches owned captured head");mc.playerController.interactWithEntity(mc.player,target.craft,EnumHand.MAIN_HAND);stage=10;frames=0;return false;}
        if(stage==10){if(!(mc.currentScreen instanceof GuiCoupler)){need(frames<60,"real captured-head Configurizer opens dedicated Coupler dialog; actual="+(mc.currentScreen==null?"null":mc.currentScreen.getClass().getSimpleName()));return false;}done=true;System.out.println("[vandorlabs][reprolab] carried-arm-coupler-live PASS checks="+checks+" actual item mounting/support/payload/capture/player input/full stroke/independent head coincidence/reversal/moving saved replacement/captured dedicated dialog; multi-pair and public activation pending");return true;}

        return false;
    }
    private VehicleArmCouplerLiveChecks(){}
}
